/**
 * Docusaurus sidebars as native navigation. Sidebars are normalised,
 * autogenerated items expanded and categories post-processed as the docs
 * plugin (3.x) does, then each category becomes a native group.
 */
import { posix } from "node:path";
import { load as parseYaml } from "js-yaml";
import type { GroupConfig, NavigationItem } from "../../config.js";
import type { Diagnostics } from "../diagnostics.js";
import { groupIds, placeUnlisted, topLevelGroups } from "../navigation.js";
import type { ProjectFiles } from "../project-files.js";
import { githubSlugs } from "../slugs.js";
import { frontmatterNumber, isCategoryIndex, numberPrefix, type DocusaurusDoc } from "./docs.js";
import type { DocsInstance, DocusaurusSite } from "./site.js";

type CategoryLink = { type: "doc"; id: string } | { type: "generated-index"; slug?: string; title?: string; description?: string };
type Item =
  | { type: "doc" | "ref"; id: string; label?: string }
  | { type: "link"; href: string; label: string }
  | { type: "html"; value: string }
  | { type: "autogenerated"; dirName: string }
  | { type: "category"; label: string; items: Item[]; link?: CategoryLink; collapsed?: boolean; collapsible?: boolean; description?: string };
type Category = Extract<Item, { type: "category" }>;

interface CategoryMetadata {
  label?: string;
  position?: number;
  collapsed?: boolean;
  collapsible?: boolean;
  link?: CategoryLink | null;
  description?: string;
}

/** A category index page Docusaurus generated, which the migration writes as an authored page. */
export interface GeneratedIndex {
  /** Path below the docs route. */
  path: string;
  title: string;
  description?: string;
  /** The native group it lists. */
  section: string;
}

export interface SidebarNavigation {
  groups: GroupConfig[];
  /** Native group IDs by the slug of the page each lands on. */
  sections: Map<string, string>;
  indexes: GeneratedIndex[];
}

export interface SidebarContext {
  project: ProjectFiles;
  diagnostics: Diagnostics;
  site: DocusaurusSite;
  instance: DocsInstance;
  /** This version's sidebars file: `false` without sidebars, undefined for the autogenerated default. */
  sidebarPath: string | false | undefined;
  contentDir: string;
  docs: DocusaurusDoc[];
  /** A document's native page reference and public route. */
  reference(doc: DocusaurusDoc): string;
  route(path: string): string;
}

export async function convertSidebars(context: SidebarContext): Promise<SidebarNavigation> {
  const { diagnostics, instance, docs, sidebarPath } = context;
  const file = typeof sidebarPath === "string" ? context.project.path(sidebarPath) : undefined;
  // A versioned sidebars file may be missing; that version has no sidebars.
  const loaded = sidebarPath === false || (file && !(await context.project.exists(file))) ? {} : file ? await context.site.load(file) : { defaultSidebar: [{ type: "autogenerated", dirName: "." }] };
  const sidebars = Object.entries((loaded ?? {}) as Record<string, unknown>).map(([id, items]) => [id, normalise(items)] as const);
  if (sidebars.length > 1)
    diagnostics.review({ file: file ?? context.site.configFile, code: "docusaurus-sidebars", message: `Sidebars ${sidebars.map(([id]) => id).join(", ")} become sections of one navigation` });

  const metadata = await categoriesMetadata(context);
  const drafts = new Set(docs.filter((doc) => doc.draft).map((doc) => doc.id));
  const { create } = await githubSlugs();
  const labels = create();
  const byId = new Map(docs.map((doc) => [doc.id, doc]));
  const result: SidebarNavigation = { groups: [], sections: new Map(), indexes: [] };
  const listed = new Set<string>();

  const expand = (items: Item[]): Item[] =>
    items.flatMap((item) => (item.type === "autogenerated" ? expand(autogenerate(item.dirName, docs, metadata, instance.numberPrefixes)) : item.type === "category" ? [{ ...item, items: expand(item.items) }] : [item]));

  const doc = (id: string, where: string) => {
    const found = byId.get(id);
    if (!found) diagnostics.error({ file: file ?? context.site.configFile, code: "docusaurus-sidebars", message: `${where} names doc "${id}", which is not in ${instance.path}` });
    return found;
  };

  const groupId = groupIds();
  const convert = (item: Item, parent: string): NavigationItem | undefined => {
    if (item.type === "link") return { href: item.href, label: item.label };
    if (item.type === "html") {
      diagnostics.review({ file: file ?? context.site.configFile, code: "docusaurus-sidebars", message: "An HTML sidebar item is not carried over" });
      return undefined;
    }
    if (item.type === "doc" || item.type === "ref") {
      if (drafts.has(item.id)) return undefined;
      const found = doc(item.id, "The sidebar");
      if (!found) return undefined;
      listed.add(found.id);
      return item.label && item.label !== found.label ? { page: context.reference(found), label: item.label } : context.reference(found);
    }
    if (item.type !== "category") return undefined;
    const id = groupId(parent, item.label, "category");
    const pages = item.items.map((child) => convert(child, id)).filter((child): child is NavigationItem => !!child);
    const link = item.link?.type === "doc" && drafts.has(item.link.id) ? undefined : item.link;
    const landing = link?.type === "doc" ? doc(link.id, `Category "${item.label}"`) : undefined;
    if (landing) listed.add(landing.id);
    // Docusaurus shows an emptied category as a link to its own page, or drops it.
    if (!pages.length) return landing ? { page: context.reference(landing), label: item.label } : undefined;
    let href: string | undefined;
    if (landing) {
      href = context.route(landing.slug);
      result.sections.set(landing.slug, id);
      // The category's own page is reached from its label; it stays published even when not listed.
      if (!pages.includes(context.reference(landing))) pages.unshift({ page: context.reference(landing), hidden: true });
    } else if (link?.type === "generated-index") {
      const path = (link.slug ?? `/category/${labels.slug(item.label)}`).replace(/^\/+|\/+$/g, "");
      href = context.route(`/${path}`);
      result.indexes.push({ path, title: link.title ?? item.label, description: link.description ?? item.description, section: id });
      pages.unshift({ page: path, hidden: true });
    }
    const collapsed = (item.collapsible ?? instance.sidebarCollapsible) && (item.collapsed ?? instance.sidebarCollapsed);
    return { group: item.label, id, ...(href ? { href } : {}), ...(collapsed ? { collapsed: true } : {}), pages };
  };

  for (const [, items] of sidebars) result.groups.push(...topLevelGroups(expand(items).map((item) => convert(item, "")).filter((item): item is NavigationItem => !!item), result.groups.length));
  placeUnlisted(result.groups, docs.filter((entry) => !entry.draft && !listed.has(entry.id)).map((entry) => context.reference(entry)));
  return result;
}

/** Sidebar items in their long form: strings are docs, a type-less object is a map of category labels to items. */
function normalise(items: unknown): Item[] {
  if (!Array.isArray(items)) return Object.entries((items ?? {}) as Record<string, unknown>).map(([label, children]) => ({ type: "category", label, items: normalise(children) }));
  return items.flatMap((item): Item[] => {
    if (typeof item === "string") return [{ type: "doc", id: item }];
    if (item && typeof item === "object" && !("type" in item)) return normalise(item);
    if ((item as Item).type === "category") return [{ ...(item as Category), items: normalise((item as Category).items) }];
    return [item as Item];
  });
}

/** `_category_.json` and `.yml` metadata, by directory inside the content directory. */
async function categoriesMetadata(context: SidebarContext): Promise<Map<string, CategoryMetadata>> {
  const files = await context.project.list(context.contentDir, (path) => /(^|\/)_category_\.(json|ya?ml)$/.test(path));
  const metadata = new Map<string, CategoryMetadata>();
  // Docusaurus reads JSON category files as YAML too, so a byte order mark is fine.
  for (const file of files) {
    const read = parseYaml(await context.project.readText(file)) as CategoryMetadata & { position?: unknown };
    metadata.set(posix.dirname(file.slice(context.contentDir.length + 1)), { ...read, position: frontmatterNumber(read.position) });
  }
  return metadata;
}

/** The default sidebar items generator: the directory's docs and subdirectories, by position then file name. */
function autogenerate(dirName: string, docs: DocusaurusDoc[], metadata: ReadonlyMap<string, CategoryMetadata>, prefixes: boolean): Item[] {
  const root = dirName.replace(/^\.\/?|\/$/g, "") || ".";
  interface Directory { [name: string]: Directory | DocusaurusDoc }
  const tree: Directory = {};
  for (const doc of docs) {
    if (root !== "." && doc.sourceDirName !== root && !doc.sourceDirName.startsWith(`${root}/`)) continue;
    const inside = root === "." ? doc.sourceDirName : doc.sourceDirName.slice(root.length + 1);
    let directory = tree;
    for (const part of inside && inside !== "." ? inside.split("/") : []) directory = (directory[part] ??= {}) as Directory;
    directory[posix.basename(doc.source)] = doc;
  }

  /** An item with the keys Docusaurus sorts it by: position, then file or folder name. */
  interface Entry {
    item: Item;
    position?: number;
    source: string;
  }
  const isDoc = (value: Directory | DocusaurusDoc): value is DocusaurusDoc => typeof (value as DocusaurusDoc).id === "string" && typeof (value as DocusaurusDoc).source === "string";
  const sort = (entries: Entry[]): Item[] =>
    [...entries].sort((a, b) => (a.position ?? Infinity) - (b.position ?? Infinity) || (a.source < b.source ? -1 : a.source > b.source ? 1 : 0)).map((entry) => entry.item);
  const toEntries = (directory: Directory, path: string): Entry[] =>
    Object.entries(directory).map(([name, value]): Entry => {
      if (isDoc(value)) return { item: { type: "doc", id: value.id, ...(value.frontmatter.sidebar_label !== undefined ? { label: value.label } : {}) }, position: value.position, source: name };
      const full = posix.join(path, name);
      const category = metadata.get(root === "." ? full : posix.join(root, full));
      const docItems = Object.values(value).filter(isDoc);
      // A doc link names the category's page by local or full ID; another link (or null) replaces the index-file convention.
      const explicit = category?.link;
      const linked =
        explicit === undefined
          ? docItems.find((doc) => isCategoryIndex(doc.source))
          : explicit?.type === "doc"
            ? docItems.find((doc) => doc.id === explicit.id || doc.id.split("/").pop() === explicit.id)
            : undefined;
      const { name: label, position } = numberPrefix(name, prefixes);
      return {
        item: {
          type: "category",
          label: category?.label ?? linked?.label ?? label,
          collapsible: category?.collapsible,
          collapsed: category?.collapsed,
          items: sort(toEntries(value, full).filter((entry) => !(entry.item.type === "doc" && entry.item.id === linked?.id))),
          ...(category?.description ? { description: category.description } : {}),
          ...(linked ? { link: { type: "doc", id: linked.id } } : category?.link ? { link: category.link } : {}),
        },
        position: category?.position ?? linked?.position ?? position,
        source: name,
      };
    });
  return sort(toEntries(tree, ""));
}
